#!/bin/bash
# 完整的一键部署脚本 - 在 EC2 浏览器终端中执行

set -e

echo "========================================"
echo "🚀 开始部署交易机器人"
echo "========================================"

# 1. 创建目录
mkdir -p ~/trading-bot
cd ~/trading-bot

echo ""
echo "📦 步骤 1/6: 创建配置文件"

# 创建 requirements.txt
cat > requirements.txt << 'EOF'
ccxt>=4.0.0
pandas>=2.0.0
python-dotenv>=1.0.0
flask>=2.3.0
requests>=2.31.0
EOF

# 创建 Dockerfile
cat > Dockerfile << 'EOF'
FROM python:3.11-slim

WORKDIR /app

# 安装系统依赖
RUN apt-get update && apt-get install -y --no-install-recommends \
    gcc \
    curl \
    && rm -rf /var/lib/apt/lists/*

# 复制依赖文件
COPY requirements.txt .

# 安装 Python 依赖
RUN pip install --no-cache-dir -r requirements.txt

# 复制应用代码
COPY app.py .
COPY new_strategy_bot.py .

# 创建数据目录
RUN mkdir -p /app/data

# 暴露端口
EXPOSE 7860

# 环境变量
ENV PYTHONUNBUFFERED=1
ENV DATA_DIR=/app/data

# 启动命令
CMD ["python", "app.py"]
EOF

# 创建 docker-compose.yml
cat > docker-compose.yml << 'EOF'
version: '3.8'

services:
  trading-bot:
    build: .
    container_name: trading-bot
    restart: unless-stopped
    ports:
      - "7860:7860"
    volumes:
      - bot-data:/app/data
      - ./binance_config.env:/app/binance_config.env:ro
    environment:
      - PYTHONUNBUFFERED=1
      - DATA_DIR=/app/data
    healthcheck:
      test: ["CMD", "curl", "-f", "http://localhost:7860/health"]
      interval: 30s
      timeout: 10s
      retries: 3
      start_period: 40s

volumes:
  bot-data:
EOF

# 创建 binance_config.env 模板
cat > binance_config.env.template << 'EOF'
OKX_API_KEY=your_api_key_here
OKX_SECRET_KEY=your_secret_key_here
OKX_PASSPHRASE=your_passphrase_here
TELEGRAM_TOKEN=
TELEGRAM_CHAT_ID=
EOF

echo ""
echo "📝 步骤 2/6: 创建 binance_config.env (请修改为你的真实 API 密钥！)"
cp binance_config.env.template binance_config.env

echo ""
echo "🐍 步骤 3/6: 创建 Python 代码文件"

# 创建 app.py (通过 base64 解码)
cat > app.py.base64 << 'EOF'
